&lt;?xml version="1.0" encoding="utf-8"?&gt;
&lt;Document&gt;
  &lt;Engineering version="V17" /&gt;
  &lt;SW.Blocks.FC ID="0"&gt;
    &lt;AttributeList&gt;
      &lt;AutoNumber&gt;true&lt;/AutoNumber&gt;
      &lt;HeaderAuthor /&gt;
      &lt;HeaderFamily /&gt;
      &lt;HeaderName /&gt;
      &lt;HeaderVersion&gt;0.1&lt;/HeaderVersion&gt;
      &lt;Interface&gt;&lt;Sections xmlns="http://www.siemens.com/automation/Openness/SW/Interface/v5"&gt;
  &lt;Section Name="Input" /&gt;
  &lt;Section Name="Output" /&gt;
  &lt;Section Name="InOut" /&gt;
  &lt;Section Name="Temp" /&gt;
  &lt;Section Name="Constant" /&gt;
  &lt;Section Name="Return"&gt;
    &lt;Member Name="Ret_Val" Datatype="Void" Accessibility="Public" /&gt;
  &lt;/Section&gt;
&lt;/Sections&gt;&lt;/Interface&gt;
      &lt;IsIECCheckEnabled&gt;false&lt;/IsIECCheckEnabled&gt;
      &lt;MemoryLayout&gt;Optimized&lt;/MemoryLayout&gt;
      &lt;Name&gt;烧嘴报警&lt;/Name&gt;
      &lt;ProgrammingLanguage&gt;LAD&lt;/ProgrammingLanguage&gt;
      &lt;SetENOAutomatically&gt;false&lt;/SetENOAutomatically&gt;
    &lt;/AttributeList&gt;
    &lt;ObjectList&gt;
      &lt;!-- ===== 梯级1：7路故障反馈并联汇总 ===== --&gt;
      &lt;SW.Blocks.CompileUnit ID="1" CompositionName="CompileUnits"&gt;
        &lt;AttributeList&gt;
          &lt;NetworkSource&gt;&lt;FlgNet xmlns="http://www.siemens.com/automation/Openness/SW/NetworkSource/FlgNet/v4"&gt;
  &lt;Parts&gt;
    &lt;!-- 7个故障反馈 Access --&gt;
    &lt;Access Scope="GlobalVariable" UId="1"&gt;
      &lt;Symbol&gt;&lt;Component Name="1#故障反馈" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="2"&gt;
      &lt;Symbol&gt;&lt;Component Name="2#故障反馈" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="3"&gt;
      &lt;Symbol&gt;&lt;Component Name="3#故障反馈" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="4"&gt;
      &lt;Symbol&gt;&lt;Component Name="4#故障反馈" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="5"&gt;
      &lt;Symbol&gt;&lt;Component Name="5#故障反馈" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="6"&gt;
      &lt;Symbol&gt;&lt;Component Name="6#故障反馈" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="7"&gt;
      &lt;Symbol&gt;&lt;Component Name="7#故障反馈" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;!-- 故障汇总 Coil operand --&gt;
    &lt;Access Scope="GlobalVariable" UId="8"&gt;
      &lt;Symbol&gt;&lt;Component Name="内部数据" /&gt;&lt;Component Name="故障汇总" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;!-- Part: 7个Contact → 级联O块 → Coil --&gt;
    &lt;!-- 分支1: Contact1-4 → O_A(Card=4) --&gt;
    &lt;Part Name="Contact" UId="10" /&gt;
    &lt;Part Name="Contact" UId="11" /&gt;
    &lt;Part Name="Contact" UId="12" /&gt;
    &lt;Part Name="Contact" UId="13" /&gt;
    &lt;Part Name="O" UId="14"&gt;
      &lt;TemplateValue Name="Card" Type="Cardinality"&gt;4&lt;/TemplateValue&gt;
    &lt;/Part&gt;
    &lt;!-- 分支2: Contact5-7 → O_B(Card=3) --&gt;
    &lt;Part Name="Contact" UId="15" /&gt;
    &lt;Part Name="Contact" UId="16" /&gt;
    &lt;Part Name="Contact" UId="17" /&gt;
    &lt;Part Name="O" UId="18"&gt;
      &lt;TemplateValue Name="Card" Type="Cardinality"&gt;3&lt;/TemplateValue&gt;
    &lt;/Part&gt;
    &lt;!-- 分支3: O_A + O_B → O_C(Card=2) → Coil --&gt;
    &lt;Part Name="O" UId="19"&gt;
      &lt;TemplateValue Name="Card" Type="Cardinality"&gt;2&lt;/TemplateValue&gt;
    &lt;/Part&gt;
    &lt;Part Name="Coil" UId="20" /&gt;
  &lt;/Parts&gt;
  &lt;Wires&gt;
    &lt;!-- Powerrail → 7个Contact.in --&gt;
    &lt;Wire UId="30"&gt;
      &lt;Powerrail /&gt;
      &lt;NameCon UId="10" Name="in" /&gt;
      &lt;NameCon UId="11" Name="in" /&gt;
      &lt;NameCon UId="12" Name="in" /&gt;
      &lt;NameCon UId="13" Name="in" /&gt;
      &lt;NameCon UId="15" Name="in" /&gt;
      &lt;NameCon UId="16" Name="in" /&gt;
      &lt;NameCon UId="17" Name="in" /&gt;
    &lt;/Wire&gt;
    &lt;!-- 分支1 operand连线 --&gt;
    &lt;Wire UId="31"&gt;&lt;IdentCon UId="1" /&gt;&lt;NameCon UId="10" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="32"&gt;&lt;IdentCon UId="2" /&gt;&lt;NameCon UId="11" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="33"&gt;&lt;IdentCon UId="3" /&gt;&lt;NameCon UId="12" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="34"&gt;&lt;IdentCon UId="4" /&gt;&lt;NameCon UId="13" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;!-- 分支1 Contact.out → O_A.in1~in4 --&gt;
    &lt;Wire UId="35"&gt;&lt;NameCon UId="10" Name="out" /&gt;&lt;NameCon UId="14" Name="in1" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="36"&gt;&lt;NameCon UId="11" Name="out" /&gt;&lt;NameCon UId="14" Name="in2" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="37"&gt;&lt;NameCon UId="12" Name="out" /&gt;&lt;NameCon UId="14" Name="in3" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="38"&gt;&lt;NameCon UId="13" Name="out" /&gt;&lt;NameCon UId="14" Name="in4" /&gt;&lt;/Wire&gt;
    &lt;!-- 分支2 operand连线 --&gt;
    &lt;Wire UId="39"&gt;&lt;IdentCon UId="5" /&gt;&lt;NameCon UId="15" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="40"&gt;&lt;IdentCon UId="6" /&gt;&lt;NameCon UId="16" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="41"&gt;&lt;IdentCon UId="7" /&gt;&lt;NameCon UId="17" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;!-- 分支2 Contact.out → O_B.in1~in3 --&gt;
    &lt;Wire UId="42"&gt;&lt;NameCon UId="15" Name="out" /&gt;&lt;NameCon UId="18" Name="in1" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="43"&gt;&lt;NameCon UId="16" Name="out" /&gt;&lt;NameCon UId="18" Name="in2" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="44"&gt;&lt;NameCon UId="17" Name="out" /&gt;&lt;NameCon UId="18" Name="in3" /&gt;&lt;/Wire&gt;
    &lt;!-- O_A.out + O_B.out → O_C.in1 + O_C.in2 --&gt;
    &lt;Wire UId="45"&gt;&lt;NameCon UId="14" Name="out" /&gt;&lt;NameCon UId="19" Name="in1" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="46"&gt;&lt;NameCon UId="18" Name="out" /&gt;&lt;NameCon UId="19" Name="in2" /&gt;&lt;/Wire&gt;
    &lt;!-- O_C.out → Coil.in --&gt;
    &lt;Wire UId="47"&gt;&lt;NameCon UId="19" Name="out" /&gt;&lt;NameCon UId="20" Name="in" /&gt;&lt;/Wire&gt;
    &lt;!-- Coil.operand ← 故障汇总 --&gt;
    &lt;Wire UId="48"&gt;&lt;IdentCon UId="8" /&gt;&lt;NameCon UId="20" Name="operand" /&gt;&lt;/Wire&gt;
  &lt;/Wires&gt;
&lt;/FlgNet&gt;&lt;/NetworkSource&gt;
          &lt;ProgrammingLanguage&gt;LAD&lt;/ProgrammingLanguage&gt;
        &lt;/AttributeList&gt;
      &lt;/SW.Blocks.CompileUnit&gt;

      &lt;!-- ===== 梯级2：P_TRIG上升沿检测 + 置位蜂鸣器 ===== --&gt;
      &lt;SW.Blocks.CompileUnit ID="2" CompositionName="CompileUnits"&gt;
        &lt;AttributeList&gt;
          &lt;NetworkSource&gt;&lt;FlgNet xmlns="http://www.siemens.com/automation/Openness/SW/NetworkSource/FlgNet/v4"&gt;
  &lt;Parts&gt;
    &lt;!-- 故障汇总用于Contact operand --&gt;
    &lt;Access Scope="GlobalVariable" UId="50"&gt;
      &lt;Symbol&gt;&lt;Component Name="内部数据" /&gt;&lt;Component Name="故障汇总" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;!-- 故障汇总用于P_TRIG的CLK --&gt;
    &lt;Access Scope="GlobalVariable" UId="51"&gt;
      &lt;Symbol&gt;&lt;Component Name="内部数据" /&gt;&lt;Component Name="故障汇总" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;!-- 蜂鸣器用于SCoil operand --&gt;
    &lt;Access Scope="GlobalVariable" UId="52"&gt;
      &lt;Symbol&gt;&lt;Component Name="蜂鸣器" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;!-- Contact(故障汇总) → P_TRIG → SCoil(蜂鸣器) --&gt;
    &lt;Part Name="Contact" UId="53" /&gt;
    &lt;Part Name="P_TRIG" UId="54"&gt;
      &lt;Instance UId="55" Scope="GlobalVariable"&gt;
        &lt;Symbol&gt;&lt;Component Name="内部数据" /&gt;&lt;Component Name="报警脉冲" /&gt;&lt;/Symbol&gt;
      &lt;/Instance&gt;
    &lt;/Part&gt;
    &lt;Part Name="SCoil" UId="56" /&gt;
  &lt;/Parts&gt;
  &lt;Wires&gt;
    &lt;!-- Powerrail → Contact.in --&gt;
    &lt;Wire UId="60"&gt;
      &lt;Powerrail /&gt;
      &lt;NameCon UId="53" Name="in" /&gt;
    &lt;/Wire&gt;
    &lt;!-- Contact.operand ← 故障汇总 --&gt;
    &lt;Wire UId="61"&gt;&lt;IdentCon UId="50" /&gt;&lt;NameCon UId="53" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;!-- Contact.out → P_TRIG.pre --&gt;
    &lt;Wire UId="62"&gt;&lt;NameCon UId="53" Name="out" /&gt;&lt;NameCon UId="54" Name="pre" /&gt;&lt;/Wire&gt;
    &lt;!-- P_TRIG.CLK ← 故障汇总 --&gt;
    &lt;Wire UId="63"&gt;&lt;IdentCon UId="51" /&gt;&lt;NameCon UId="54" Name="CLK" /&gt;&lt;/Wire&gt;
    &lt;!-- P_TRIG.Q → SCoil.in --&gt;
    &lt;Wire UId="64"&gt;&lt;NameCon UId="54" Name="Q" /&gt;&lt;NameCon UId="56" Name="in" /&gt;&lt;/Wire&gt;
    &lt;!-- SCoil.operand ← 蜂鸣器 --&gt;
    &lt;Wire UId="65"&gt;&lt;IdentCon UId="52" /&gt;&lt;NameCon UId="56" Name="operand" /&gt;&lt;/Wire&gt;
  &lt;/Wires&gt;
&lt;/FlgNet&gt;&lt;/NetworkSource&gt;
          &lt;ProgrammingLanguage&gt;LAD&lt;/ProgrammingLanguage&gt;
        &lt;/AttributeList&gt;
      &lt;/SW.Blocks.CompileUnit&gt;

      &lt;!-- ===== 梯级3：6路超温标志并联汇总 ===== --&gt;
      &lt;SW.Blocks.CompileUnit ID="3" CompositionName="CompileUnits"&gt;
        &lt;AttributeList&gt;
          &lt;NetworkSource&gt;&lt;FlgNet xmlns="http://www.siemens.com/automation/Openness/SW/NetworkSource/FlgNet/v4"&gt;
  &lt;Parts&gt;
    &lt;!-- 6个超温标志 Access --&gt;
    &lt;Access Scope="GlobalVariable" UId="70"&gt;
      &lt;Symbol&gt;&lt;Component Name="数字量信号" /&gt;&lt;Component Name="1区超温标志" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="71"&gt;
      &lt;Symbol&gt;&lt;Component Name="数字量信号" /&gt;&lt;Component Name="2区超温标志" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="72"&gt;
      &lt;Symbol&gt;&lt;Component Name="数字量信号" /&gt;&lt;Component Name="3区超温标志" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="73"&gt;
      &lt;Symbol&gt;&lt;Component Name="数字量信号" /&gt;&lt;Component Name="4区超温标志" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="74"&gt;
      &lt;Symbol&gt;&lt;Component Name="数字量信号" /&gt;&lt;Component Name="5区超温标志" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;Access Scope="GlobalVariable" UId="75"&gt;
      &lt;Symbol&gt;&lt;Component Name="数字量信号" /&gt;&lt;Component Name="6区超温标志" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;!-- 控温超温标志 Coil operand --&gt;
    &lt;Access Scope="GlobalVariable" UId="76"&gt;
      &lt;Symbol&gt;&lt;Component Name="内部数据" /&gt;&lt;Component Name="控温超温标志" /&gt;&lt;/Symbol&gt;
    &lt;/Access&gt;
    &lt;!-- Part: 6个Contact → 级联O块 → Coil --&gt;
    &lt;!-- 分支1: Contact(1区,2区,3区) → O_D(Card=3) --&gt;
    &lt;Part Name="Contact" UId="80" /&gt;
    &lt;Part Name="Contact" UId="81" /&gt;
    &lt;Part Name="Contact" UId="82" /&gt;
    &lt;Part Name="O" UId="83"&gt;
      &lt;TemplateValue Name="Card" Type="Cardinality"&gt;3&lt;/TemplateValue&gt;
    &lt;/Part&gt;
    &lt;!-- 分支2: Contact(4区,5区,6区) → O_E(Card=3) --&gt;
    &lt;Part Name="Contact" UId="84" /&gt;
    &lt;Part Name="Contact" UId="85" /&gt;
    &lt;Part Name="Contact" UId="86" /&gt;
    &lt;Part Name="O" UId="87"&gt;
      &lt;TemplateValue Name="Card" Type="Cardinality"&gt;3&lt;/TemplateValue&gt;
    &lt;/Part&gt;
    &lt;!-- 分支3: O_D + O_E → O_F(Card=2) → Coil --&gt;
    &lt;Part Name="O" UId="88"&gt;
      &lt;TemplateValue Name="Card" Type="Cardinality"&gt;2&lt;/TemplateValue&gt;
    &lt;/Part&gt;
    &lt;Part Name="Coil" UId="89" /&gt;
  &lt;/Parts&gt;
  &lt;Wires&gt;
    &lt;!-- Powerrail → 6个Contact.in --&gt;
    &lt;Wire UId="90"&gt;
      &lt;Powerrail /&gt;
      &lt;NameCon UId="80" Name="in" /&gt;
      &lt;NameCon UId="81" Name="in" /&gt;
      &lt;NameCon UId="82" Name="in" /&gt;
      &lt;NameCon UId="84" Name="in" /&gt;
      &lt;NameCon UId="85" Name="in" /&gt;
      &lt;NameCon UId="86" Name="in" /&gt;
    &lt;/Wire&gt;
    &lt;!-- 分支1 operand --&gt;
    &lt;Wire UId="91"&gt;&lt;IdentCon UId="70" /&gt;&lt;NameCon UId="80" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="92"&gt;&lt;IdentCon UId="71" /&gt;&lt;NameCon UId="81" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="93"&gt;&lt;IdentCon UId="72" /&gt;&lt;NameCon UId="82" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;!-- 分支1 Contact.out → O_D.in1~3 --&gt;
    &lt;Wire UId="94"&gt;&lt;NameCon UId="80" Name="out" /&gt;&lt;NameCon UId="83" Name="in1" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="95"&gt;&lt;NameCon UId="81" Name="out" /&gt;&lt;NameCon UId="83" Name="in2" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="96"&gt;&lt;NameCon UId="82" Name="out" /&gt;&lt;NameCon UId="83" Name="in3" /&gt;&lt;/Wire&gt;
    &lt;!-- 分支2 operand --&gt;
    &lt;Wire UId="97"&gt;&lt;IdentCon UId="73" /&gt;&lt;NameCon UId="84" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="98"&gt;&lt;IdentCon UId="74" /&gt;&lt;NameCon UId="85" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="99"&gt;&lt;IdentCon UId="75" /&gt;&lt;NameCon UId="86" Name="operand" /&gt;&lt;/Wire&gt;
    &lt;!-- 分支2 Contact.out → O_E.in1~3 --&gt;
    &lt;Wire UId="100"&gt;&lt;NameCon UId="84" Name="out" /&gt;&lt;NameCon UId="87" Name="in1" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="101"&gt;&lt;NameCon UId="85" Name="out" /&gt;&lt;NameCon UId="87" Name="in2" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="102"&gt;&lt;NameCon UId="86" Name="out" /&gt;&lt;NameCon UId="87" Name="in3" /&gt;&lt;/Wire&gt;
    &lt;!-- O_D.out + O_E.out → O_F.in1 + O_F.in2 --&gt;
    &lt;Wire UId="103"&gt;&lt;NameCon UId="83" Name="out" /&gt;&lt;NameCon UId="88" Name="in1" /&gt;&lt;/Wire&gt;
    &lt;Wire UId="104"&gt;&lt;NameCon UId="87" Name="out" /&gt;&lt;NameCon UId="88" Name="in2" /&gt;&lt;/Wire&gt;
    &lt;!-- O_F.out → Coil.in --&gt;
    &lt;Wire UId="105"&gt;&lt;NameCon UId="88" Name="out" /&gt;&lt;NameCon UId="89" Name="in" /&gt;&lt;/Wire&gt;
    &lt;!-- Coil.operand ← 控温超温标志 --&gt;
    &lt;Wire UId="106"&gt;&lt;IdentCon UId="76" /&gt;&lt;NameCon UId="89" Name="operand" /&gt;&lt;/Wire&gt;
  &lt;/Wires&gt;
&lt;/FlgNet&gt;&lt;/NetworkSource&gt;
          &lt;ProgrammingLanguage&gt;LAD&lt;/ProgrammingLanguage&gt;
        &lt;/AttributeList&gt;
      &lt;/SW.Blocks.CompileUnit&gt;
    &lt;/ObjectList&gt;
  &lt;/SW.Blocks.FC&gt;
&lt;/Document&gt;
